solution.solution.c:
int next_id(void)
{
    static int last = 0;
    last++;
    return last;
}

int running_total(int add)
{
    static int total = 0;
    total += add;
    return total;
}

int calls_so_far(void)
{
    static int calls = 0;
    return ++calls;
}

unitTests:
TEST("ids count up") { CHECK_EQ(next_id(), 1); CHECK_EQ(next_id(), 2); CHECK_EQ(next_id(), 3); }
TEST("a running total") { CHECK_EQ(running_total(5), 5); CHECK_EQ(running_total(10), 15); CHECK_EQ(running_total(-20), -5); CHECK_EQ(running_total(0), -5); }
TEST("counting calls") { for (int i = 1; i <= 5; i++) { CHECK_EQ(calls_so_far(), i); } }

